def platform_administrators(self, tenant_id: str, req_context=None) -> Any:
    from .enterprise import platform_governance
    try:
        return platform_governance.administrators(_identity_repo(), _ctx_or_super(req_context), tenant_id)
    except PermissionError as exc:
        raise _AuthError(str(exc)) from exc
    except ValueError as exc:
        raise DeviceError(str(exc)) from exc

